// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        uint256 boundedAmount = bound(amount, 0, 100 ether);

        uint256 initialPastBlockTime = c.pastBlockTime();

        (bool success, ) = address(c).call{value: boundedAmount}("");

        if (boundedAmount == 10 ether) {
            assertTrue(success);
        } else {
            assertTrue(!success || (boundedAmount != 10 ether));
        }
    }
}

